// partition-money-adjacent.mjs — derive the v100 big-bang partition:
//   MONEY-ADJACENT (Brain-only, EXCLUDED from the Codex bulk wave) vs NON-MONEY (Codex-eligible).
import Database from 'better-sqlite3';
import { readdirSync, existsSync } from 'node:fs';
import { join } from 'node:path';

const ROOT = process.cwd();
const crates = readdirSync(join(ROOT, 'crates'))
  .filter(d => existsSync(join(ROOT, 'crates', d, 'Cargo.toml'))).sort();

// hard money spine — BYTE-FROZEN, always Brain, never any Cloud/Codex tab
const HARD_SPINE = new Set(['chronica-policy', 'chronica-core', 'chronica-runtime', 'chronica-approvals']);
// known money-adjacent from memory (FX/threshold, ERP currency path, renamed money-adjacent store, ledger engine)
const KNOWN_ADJ = new Set(['chronica-compliance', 'chronica-erp', 'chronica-template-store',
  'chronica-billing', 'chronica-commerce', 'chronica-ledger', 'chronica-settlement', 'chronica-payments']);

const caps = new Database(join(ROOT, 'docs', 'capabilities.db'), { readonly: true });
const arch = new Database(join(ROOT, 'docs', 'architecture.db'), { readonly: true });
const safe = (fn, d) => { try { return fn(); } catch { return d; } };

// crates that any moves_money capability targets
const moneyCapCrates = new Map(); // crate -> count
safe(() => {
  for (const r of caps.prepare("SELECT target_crate c, count(*) n FROM canonical_capability WHERE moves_money=1 AND target_crate IS NOT NULL AND target_crate<>'' GROUP BY target_crate").all())
    moneyCapCrates.set(r.c, r.n);
}, null);

// dep edges (who depends on the hard spine) — informational, NOT auto money-adjacency (chronica-core is near-universal foundation)
const dependsOnSpine = new Map();
safe(() => {
  for (const sp of HARD_SPINE) {
    for (const r of arch.prepare("SELECT from_node f FROM architecture_edge WHERE to_node=? AND from_node LIKE 'crate:%'").all(`crate:${sp}`)) {
      const c = r.f.replace('crate:', '');
      if (!dependsOnSpine.has(c)) dependsOnSpine.set(c, new Set());
      dependsOnSpine.get(c).add(sp);
    }
  }
}, null);

const rows = crates.map(c => {
  const money = moneyCapCrates.get(c) || moneyCapCrates.get(c.replace('chronica-', '')) || 0;
  const spineDeps = [...(dependsOnSpine.get(c) || [])].filter(s => s !== 'chronica-core'); // ignore ubiquitous core
  let cls, reason;
  if (HARD_SPINE.has(c)) { cls = 'SPINE'; reason = 'money spine byte-frozen'; }
  else if (KNOWN_ADJ.has(c)) { cls = 'ADJ'; reason = 'known money-adjacent (memory)'; }
  else if (money > 0) { cls = 'ADJ'; reason = `${money} moves_money caps target it`; }
  else if (spineDeps.length) { cls = 'ADJ?'; reason = `depends on ${spineDeps.join('+')} (verify coupling)`; }
  else { cls = 'BULK'; reason = 'no money coupling'; }
  return { c, cls, money, spineDeps: spineDeps.join('+'), reason };
});

const by = k => rows.filter(r => r.cls === k);
console.log(`TOTAL crates: ${crates.length}`);
for (const k of ['SPINE', 'ADJ', 'ADJ?', 'BULK']) {
  const g = by(k);
  console.log(`\n== ${k} (${g.length}) ==`);
  for (const r of g) console.log(`  ${r.c.padEnd(34)} ${r.reason}`);
}
console.log(`\nEXCLUDED from Codex bulk (SPINE+ADJ+ADJ?): ${by('SPINE').length + by('ADJ').length + by('ADJ?').length}`);
console.log(`CODEX-ELIGIBLE bulk (BULK): ${by('BULK').length}`);
// emit machine list for the workflow
console.log('\nBULK_LIST=' + by('BULK').map(r => r.c).join(','));
caps.close(); arch.close();
"},"caller":{"type":"direct"}}

