${allRows.some(r => r.status !== 'active') ? `## Accepted / scheduled / paid\n\n${allRows.filter(r => r.status !== 'active').map(r => `- [${r.status}] \`${r.id}\` — ${esc(r.title)}`).join('\n')}\n` : ''}
