4	 * already-redacted, already-tenancy-enforced control-room reads into one typed
5	 * post stream. A backend `GET /companies/:id/feed` aggregation route is deferred
6	 * (it needs run records mounted + a `createdAt` field on the redacted ledger JSON).
7	 */
8	import {
9	  projectBrief,
10	  projectPendingDecision,
11	  synthAnnouncement,
12	  synthRunRollup,
13	  type Post,
14	} from "./post";
15	import { projectRun, type RuntimeRunRow } from "./runs";
16	import { projectErpEvent, type ErpEventRow } from "./erp-events";
17	import { projectArtifact, type ArtifactRow } from "./artifacts";
18	import type {
19	  BriefRow,
20	  PendingDecisionRow,
21	  SummaryResponse,
22	} from "../control-room/api";
23	
24	export interface FeedSources {
25	  pending: PendingDecisionRow[];
26	  briefs: BriefRow[];
27	  summary: SummaryResponse | null;
28	  /** Recent runtime runs → typed run_update posts (read-only metadata). */
29	  runs?: RuntimeRunRow[];
30	  /** Recent committed money/ERP events → typed erp_event posts (read-only, redacted). */
31	  erpEvents?: ErpEventRow[];
32	  /** Company artifacts → typed evidence_bundle posts with an attachment chip (read-only metadata). */
33	  artifacts?: ArtifactRow[];
34	}
