36	/**
37	 * Sort comparator: newest first by `timestamp` (decidedAt ISO), then by id DESC.
38	 * A null/empty timestamp sorts LAST (empty string is less than any ISO string, so
39	 * under descending order it falls to the bottom) — never reordered to look recent.
40	 */
41	function byRecencyDesc(a: Post, b: Post): number {
42	  const ta = a.timestamp ?? "";
43	  const tb = b.timestamp ?? "";
44	  if (ta !== tb) return ta < tb ? 1 : -1;
45	  return a.id < b.id ? 1 : -1;
46	}
47	
48	/**
49	 * Aggregate the read-model sources into the ordered feed.
50	 *
51	 * - Projects each E1 pending-decision and E2 brief row into a typed Post.
52	 * - Dedupes by id: a ledger row can surface in BOTH endpoints; the E1/pending
53	 *   projection WINS because it carries the approval half (the richer post).
54	 * - Prepends a pinned synthetic announcement, then a run rollup (when runs exist).
55	 * - Sorts the real posts newest-first; synthetic System posts stay pinned on top.
56	 */
57	export function aggregateFeed(
58	  sources: FeedSources,
59	  companyId: string,
60	  companyName: string,
61	): Post[] {
62	  const byId = new Map<string, Post>();
63	  // Briefs first, then pending overlays (E1 wins on id collision).
64	  for (const b of sources.briefs ?? []) byId.set(b.id, projectBrief(b));
65	  for (const p of sources.pending ?? []) byId.set(p.id, projectPendingDecision(p));
66	  // Run posts use a `run:`-prefixed id, so they never collide with ledger ids.
67	  for (const r of sources.runs ?? []) byId.set(`run:${r.id}`, projectRun(r, companyId));
68	  // ERP/money-event posts use an `erp:`-prefixed id (never collides with ledger/run ids).
69	  for (const e of sources.erpEvents ?? []) byId.set(`erp:${e.id}`, projectErpEvent(e, companyId));
70	  // Artifact posts use an `artifact:`-prefixed id (never collides with ledger/run/erp ids).
71	  for (const a of sources.artifacts ?? []) byId.set(`artifact:${a.id}`, projectArtifact(a, companyId));
72	
73	  const real = Array.from(byId.values()).sort(byRecencyDesc);
74	
75	  const pinned: Post[] = [];
76	  if (sources.summary) {
77	    pinned.push(synthAnnouncement(sources.summary, companyId, companyName));
78	    const rollup = synthRunRollup(sources.summary, companyId);
79	    if (rollup) pinned.push(rollup);
80	  }
81	
82	  return [...pinned, ...real];
83	}
