46	export function useFeed(companyId: string | undefined, companyName: string): FeedState {
47	  const enabled = !!companyId;
48	  const idForQuery = companyId ?? "";
49	
50	  const pendingQ = useQuery({
51	    queryKey: ["feed", "pending", companyId],
52	    queryFn: () => controlRoomApi.fetchPendingDecisions(idForQuery),
53	    enabled,
54	  });
55	  const briefsQ = useQuery({
56	    queryKey: ["feed", "briefs", companyId],
57	    queryFn: () => controlRoomApi.fetchBriefs(idForQuery),
58	    enabled,
59	  });
60	  const summaryQ = useQuery({
61	    queryKey: ["feed", "summary", companyId],
62	    queryFn: () => controlRoomApi.fetchControlRoomSummary(idForQuery),
63	    enabled,
64	  });
65	  const runsQ = useQuery({
66	    queryKey: ["feed", "runs", companyId],
67	    queryFn: () => fetchRuns(idForQuery),
68	    enabled,
69	  });
70	  const erpEventsQ = useQuery({
71	    queryKey: ["feed", "erp-events", companyId],
72	    queryFn: () => fetchErpEvents(idForQuery),
73	    enabled,
74	  });
75	  const artifactsQ = useQuery({
76	    queryKey: ["feed", "artifacts", companyId],
77	    queryFn: () => fetchArtifacts(idForQuery),
78	    enabled,
79	  });
80	
81	  const summary = summaryQ.data ?? null;
82	  // MEMOIZE: `aggregateFeed` builds a NEW array each call. Consumers (Feed.tsx) use `posts` as an
83	  // effect dependency (the RightRail `openPanel` effect); an unstable identity every render makes that
84	  // effect re-fire → setState → re-render → infinite loop ("Maximum update depth exceeded"). Keying the
85	  // memo on the (react-query-stable) source data keeps `posts` referentially stable until data changes.
86	  const posts = useMemo(
87	    () =>
88	      enabled
89	        ? aggregateFeed(
90	            {
91	              pending: pendingQ.data?.items ?? [],
92	              briefs: briefsQ.data?.items ?? [],
93	              summary,
94	              runs: runsQ.data?.runs ?? [],
95	              erpEvents: erpEventsQ.data?.events ?? [],
96	              artifacts: artifactsQ.data?.artifacts ?? [],
97	            },
98	            idForQuery,
99	            companyName,
100	          )
101	        : [],
102	    [
103	      enabled,
104	      pendingQ.data,
105	      briefsQ.data,
106	      summary,
107	      runsQ.data,
108	      erpEventsQ.data,
109	      artifactsQ.data,
110	      idForQuery,
111	      companyName,
112	    ],
113	  );
114	
115	  const pendingApprovals = pendingApprovalsBadge(summary);
116	
117	  return {
118	    posts,
119	    badge: pendingApprovals,
120	    header: {
121	      openDecisions: sumCounts(summary?.counts?.ledgerByStatus),
122	      pendingApprovals,
123	      riskStatus: deriveRisk(posts),
124	    },
125	    loading: enabled && (pendingQ.isLoading || briefsQ.isLoading || summaryQ.isLoading),
126	    error: (pendingQ.error || briefsQ.error || summaryQ.error) as Error | null,
127	  };
128	}
