 * Pure document/filename formatters for IssueDetail — extracted behavior-preserving to chip the host
 * God-File down (arch-debt ui-god-files-over-500-lines). Zero imports, zero React/state, zero parent-scope
 * closures — the safest possible seam. Moved verbatim. IssueDetail.tsx imports them back; they are not part
 * of its existing test surface, so a dedicated unit test (document-helpers.test.tsx) now covers them directly.
 */

export function truncate(text: string, max: number): string {
  if (text.length <= max) return text;
  return text.slice(0, max - 1) + "…";
}

export function isMarkdownFile(file: File) {
  const name = file.name.toLowerCase();
  return (
    name.endsWith(".md") ||
    name.endsWith(".markdown") ||
    file.type === "text/markdown"
  );
}

export function fileBaseName(filename: string) {
  return filename.replace(/\.[^.]+$/, "");
}

export function slugifyDocumentKey(input: string) {
  const slug = input
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return slug || "document";
}

export function titleizeFilename(input: string) {
  return input
    .split(/[-_ ]+/g)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}
