{"type":"tool_use","id":"toolu_01Cd6kbJFdatzqvKXFQ2U72U","name":"Write","input":{"file_path":"C:\Users\trngh\Documents\GitHub\Chronica\ui\src\pages\issue-detail\document-helpers.test.tsx","content":"import { describe, it, expect } from "vitest";
import {
  truncate,
  isMarkdownFile,
  fileBaseName,
  slugifyDocumentKey,
  titleizeFilename,
} from "./document-helpers";

// isMarkdownFile only reads `.name` and `.type`, so a minimal shape is enough (avoids the
// File global in a node test env).
function fakeFile(name: string, type = ""): File {
  return { name, type } as unknown as File;
}

describe("document-helpers", () => {
  describe("truncate", () => {
    it("returns the text unchanged when within max", () => {
      expect(truncate("hello", 5)).toBe("hello");
      expect(truncate("hi", 10)).toBe("hi");
    });

    it("truncates and appends an ellipsis when over max", () => {
      expect(truncate("hello world", 5)).toBe("hell…");
      expect(truncate("hello world", 5)).toHaveLength(5);
    });
  });

  describe("isMarkdownFile", () => {
    it("matches .md and .markdown extensions case-insensitively", () => {
      expect(isMarkdownFile(fakeFile("notes.md"))).toBe(true);
      expect(isMarkdownFile(fakeFile("README.MARKDOWN"))).toBe(true);
    });

    it("matches the text/markdown mime type", () => {
      expect(isMarkdownFile(fakeFile("notes.txt", "text/markdown"))).toBe(true);
    });

    it("rejects non-markdown files", () => {
      expect(isMarkdownFile(fakeFile("image.png", "image/png"))).toBe(false);
      expect(isMarkdownFile(fakeFile("data.json"))).toBe(false);
    });
  });

  describe("fileBaseName", () => {
    it("strips a single trailing extension", () => {
      expect(fileBaseName("report.pdf")).toBe("report");
      expect(fileBaseName("archive.tar.gz")).toBe("archive.tar");
    });

    it("leaves a name with no extension untouched", () => {
      expect(fileBaseName("README")).toBe("README");
    });
  });

  describe("slugifyDocumentKey", () => {
    it("lowercases, trims, and hyphenates non-alphanumerics", () => {
      expect(slugifyDocumentKey("  Q4 Revenue Plan! ")).toBe("q4-revenue-plan");
      expect(slugifyDocumentKey("Hello, World")).toBe("hello-world");
    });

    it("falls back to 'document' when nothing usable remains", () => {
      expect(slugifyDocumentKey("***")).toBe("document");
      expect(slugifyDocumentKey("")).toBe("document");
    });
  });

  describe("titleizeFilename", () => {
    it("splits on -, _, and spaces and capitalizes each part", () => {
      expect(titleizeFilename("q4-revenue_plan")).toBe("Q4 Revenue Plan");
      expect(titleizeFilename("hello world")).toBe("Hello World");
    });

    it("drops empty segments from repeated separators", () => {
      expect(titleizeFilename("a--b__c")).toBe("A B C");
    });
  });
});
